#!/bin/bash
ssh -o BatchMode=yes -o StrictHostKeyChecking=no -o ConnectTimeout=20 -i ~/.ssh/${K50_KEY} root@${K50_HOST} \
  'echo "=== CAMSV0 (0x1a110000) ==="; for o in 0x40 0x44 0x60 0x100 0x104 0x108 0x10c 0x110 0x138 0x13c; do echo -n "CAMSV+$o: "; busybox devmem 0x1a110000$((o)) 2>&1; done; echo "=== CAM MUX (0x1a010400) ==="; for o in 0x400 0x404 0x408 0x40c 0x410 0x418 0x420 0x4a0 0x4a8 0x500 0x504 0x508; do echo -n "MUX+$o: "; busybox devmem 0x1a010000$((o)) 2>&1; done' 2>&1
